#!/usr/bin/env node

// Machine-enforced security invariants. Each rule below exists because a
// specific incident or review found it could silently regress during normal
// work. The rules encode outcomes (what must stay true), not style. When one
// of these fails, the change is rejected; do not edit this file to make a
// change pass. Rationale: FORK.md "Rules for performance changes" and
// .github/CODE_GUIDELINES.md.
//
// Runs as part of lint-and-format. Exit 0 = invariants hold.

import { readFileSync } from "node:fs";
import process from "node:process";

const failures = [];
const fail = (rule, detail) => failures.push(`[${rule}] ${detail}`);

const read = (path) => {
	try {
		return readFileSync(path, "utf8");
	} catch {
		return null;
	}
};

// ---------------------------------------------------------------------------
// Rule 1: subprocess output never reaches API responses.
// CommandError messages carry raw certbot stdout/stderr (credentials, paths).
// The fork removed public debug payloads in 8639e5a7; upstream later shipped
// an `error.output` variant, so a future merge could reintroduce the leak as
// a "clean" upstream change. Blocks the exact shapes that leak.
// ---------------------------------------------------------------------------
{
	const app = read("backend/app.js");
	if (app !== null) {
		if (/\bpayload\.debug\b/.test(app)) {
			fail("no-subprocess-output", "backend/app.js assigns payload.debug");
		}
		if (/payload\.error\.output\s*=/.test(app)) {
			fail("no-subprocess-output", "backend/app.js assigns payload.error.output");
		}
		const errorObject = read("backend/schema/components/error-object.json");
		if (errorObject !== null && /"output"/.test(errorObject)) {
			fail(
				"no-subprocess-output",
				"backend/schema/components/error-object.json declares an output property the backend must never emit",
			);
		}
	}
	const errors = read("backend/lib/error.js");
	if (errors !== null) {
		// CommandError must never become public: public errors echo err.message.
		const match = errors.match(/CommandError:\s*function[\s\S]*?\},\n/s);
		if (match && /public:\s*true/.test(match[0])) {
			fail("no-subprocess-output", "backend/lib/error.js marks CommandError public");
		}
	}
}

// ---------------------------------------------------------------------------
// Rule 2: 401/403 semantics. jwtdecode answers 401 for a rejected session and
// routes answer 403 for permission denials. Upstream once converted anonymous
// 403s to 401; that was rejected because it stranded the UI in a ghost
// session. The status codes on these two specific files are load-bearing.
// ---------------------------------------------------------------------------
{
	const jwtdecode = read("backend/lib/express/jwt-decode.js");
	if (jwtdecode !== null) {
		// Strip line comments: a commented-out 401 must not satisfy the rule.
		const live = jwtdecode.replace(/(^|\s)\/\/.*$/gm, "$1");
		if (!/res\.status\(401\)/.test(live)) {
			fail("session-status-codes", "backend/lib/express/jwt-decode.js no longer returns 401 for rejected sessions");
		}
	}
}

// ---------------------------------------------------------------------------
// Rule 3: the admin UI index and SPA fallback stay no-store. Every image build
// produces new content-hashed chunk names; a cached index is a guaranteed
// broken app after the next update. The two location blocks that serve the
// SPA must both carry the no-store header.
// ---------------------------------------------------------------------------
{
	const conf = read("rootfs/usr/local/nginx/conf/conf.d/npmplus.conf");
	if (conf !== null) {
		const noStore = /add_header Cache-Control "no-store[^"]*"/;
		for (const block of [`location = / {`, `location / {`]) {
			const start = conf.indexOf(block);
			if (start === -1) {
				fail("no-store-index", `npmplus.conf no longer has the "${block}" block`);
				continue;
			}
			const end = conf.indexOf("\n  }", start);
			const section = conf.slice(start, end === -1 ? undefined : end);
			if (!noStore.test(section)) {
				fail("no-store-index", `"${block}" lost its no-store Cache-Control header`);
			}
		}
	}
}

// ---------------------------------------------------------------------------
// Rule 4: logout revocation is enforced per request at the access layer.
// The fork tracks refresh sessions in the database; a cookie/token replayed
// after logout must fail here (assertTokenSession in access.js init), not
// only in the MFA challenge path. Upstream does not have this check, so a
// future merge could drop it as an "upstream simplification". The Ajv
// permission cache this rule originally guarded was removed with upstream's
// plain can()/canUser() permission model; identity is now per-request by
// construction, but the session check must survive every merge.
// ---------------------------------------------------------------------------
{
	const access = read("backend/lib/access.js");
	if (access !== null) {
		if (!/assertTokenSession\(/.test(access)) {
			fail("session-revocation-access", "backend/lib/access.js no longer calls assertTokenSession");
		}
	}
	const token = read("backend/internal/token.js");
	if (token !== null && !/assertTokenSession\(/.test(token)) {
		fail("session-revocation-access", "backend/internal/token.js no longer calls assertTokenSession");
	}
}

// ---------------------------------------------------------------------------
// Rule 5: external fetches stay bounded. lib/bounded-fetch.js is the only
// sanctioned outbound fetch surface; widening its contracts (removing the
// timeout or the byte cap) or routing new call sites around it is how
// unbounded external reads sneak in. The helpers themselves must keep both
// bounds.
// ---------------------------------------------------------------------------
{
	const bounded = read("backend/lib/bounded-fetch.js");
	if (bounded !== null) {
		if (!/AbortSignal\.timeout\(timeoutMs\)/.test(bounded)) {
			fail("bounded-fetch", "backend/lib/bounded-fetch.js lost its timeout signal construction");
		}
		if (!/total > maxBytes/.test(bounded) || !/declaredLength > maxBytes/.test(bounded)) {
			fail("bounded-fetch", "backend/lib/bounded-fetch.js lost its byte cap enforcement");
		}
	}
}

// ---------------------------------------------------------------------------
// Rule 6: the merged permission model fails closed on malformed inputs.
// can() must reject permission strings without a "type:level" shape (the
// split otherwise compares undefined === undefined and grants), and canUser()
// must reject the anonymous-session sentinel 0 and non-ids (otherwise
// canUser("0") passes for an anonymous session). Both guards came out of the
// 2026-09-16 security review; a future merge could drop them as "simpler
// upstream shapes" and neither would fail any other test.
// ---------------------------------------------------------------------------
{
	const access = read("backend/lib/access.js");
	if (access !== null) {
		if (!/typeof\s+required\s*!==\s*"string"/.test(access)) {
			fail("fail-closed-permissions", "backend/lib/access.js can() no longer rejects colon-less permission strings");
		}
		if (!/Number\.isInteger\(userId\)/.test(access) || !/userId\s*<\s*1/.test(access)) {
			fail("fail-closed-permissions", "backend/lib/access.js canUser() no longer rejects the anonymous sentinel and non-ids");
		}
	}
}

// ---------------------------------------------------------------------------
// Rule 7: fork-only package.json lines survive upstream merges. The 2026-09-17
// sync resolved both manifests with upstream's whole file, which silently
// dropped the fork author attribution and the scripts.test entry CI's
// `pnpm test` step runs. Upstream's manifests do not carry these lines, so a
// wholesale-theirs resolution can remove them as a "clean" upstream change.
// ---------------------------------------------------------------------------
{
	for (const path of ["backend/package.json", "frontend/package.json"]) {
		const manifest = read(path);
		if (manifest === null) {
			continue;
		}
		if (!/"author"\s*:\s*"[^"]*mangyan1/.test(manifest)) {
			fail("fork-manifest-lines", `${path} lost the fork author attribution`);
		}
		if (!/"test"\s*:\s*"node --test/.test(manifest)) {
			fail("fork-manifest-lines", `${path} lost the scripts.test entry CI's pnpm test step runs`);
		}
	}
}

// ---------------------------------------------------------------------------
// Rule 8: the crowdsec data dir is dereferenced before the hub refresh. The
// image entrypoint links its preloaded datafiles into /var/lib/crowdsec/data as
// absolute symlinks into /staging, and the read_only hardening turns that
// target read-only: `cscli hub upgrade` follows the link into an EROFS and
// aborts the whole upgrade. The container's own copy of that call is silenced
// with `|| true`, so the failure is a single warning line in an update log and
// no detection signature ever refreshes. Reported from the field 2026-09-19.
// ---------------------------------------------------------------------------
{
	const setup = read("setup-npmplus.sh");
	if (setup !== null) {
		// anchored to the command form: the installer also *names* these commands
		// in its own operator messages ("... until: docker exec crowdsec cscli hub
		// upgrade"), and matching that prose would anchor the rule to the wrong
		// line - it did, the first time the seed message was added.
		const upgradeAt = setup.search(/^[ \t]*docker exec crowdsec cscli hub upgrade/m);
		const dereferenceAt = setup.search(
			/^[ \t]*docker exec crowdsec sh -c 'cd \/var\/lib\/crowdsec\/data[\s\S]{0,400}?cp -Lpf/m,
		);
		if (upgradeAt === -1) {
			fail("crowdsec-datafiles", "setup-npmplus.sh no longer refreshes the crowdsec hub");
		} else if (dereferenceAt === -1 || dereferenceAt > upgradeAt) {
			fail(
				"crowdsec-datafiles",
				"setup-npmplus.sh must dereference /var/lib/crowdsec/data before `cscli hub upgrade` (read_only /staging symlinks abort it with EROFS)",
			);
		}
		// The upgrade path repairs an existing install; a fresh one must never
		// reach that state: the datafiles are seeded while the container is still
		// down, so the entrypoint finds them and links nothing into /staging.
		// Drop this and every new install aborts its own startup hub refresh.
		const installAt = setup.indexOf('say "starting crowdsec"');
		const installUpAt =
			installAt === -1 ? -1 : setup.indexOf('docker compose -f "$COMPOSE_FILE" up -d crowdsec', installAt);
		const seedAt = setup.search(/^[ \t]*seed_crowdsec_datafiles "\$CROWDSEC_IMAGE"/m);
		if (installAt === -1 || installUpAt === -1) {
			fail("crowdsec-datafiles", "setup-npmplus.sh no longer starts crowdsec from the installer body");
		} else if (seedAt === -1 || seedAt < installAt || seedAt > installUpAt) {
			fail(
				"crowdsec-datafiles",
				'setup-npmplus.sh must seed the crowdsec datafiles (seed_crowdsec_datafiles "$CROWDSEC_IMAGE") between `say "starting crowdsec"` and the install-time `up -d crowdsec`',
			);
		}
	}
}

if (failures.length > 0) {
	console.error("security invariant violations:");
	for (const failure of failures) {
		console.error(`  ${failure}`);
	}
	console.error("");
	console.error("These are load-bearing security properties, not style rules.");
	console.error("Fix the change, or redesign the invariant with owner approval");
	console.error("(see .github/CODE_GUIDELINES.md and FORK.md) - never edit this check to pass.");
	process.exit(1);
}
console.log("security invariants: ok");